function makeZone(task='receive'){const t=TASKS.find(x=>x.id===task)||TASKS[0];return{id:uid(),task:t.id,tasks:[t.id],name:t.name,length:1.5,lane:'main',anchor:null,reference:t.refs[0]||'',aux:[],level:LEVELS[0],status:STATUSES[0],effect:'',capability:'',supplyNote:'',materials:[],heating:[],flowFactor:null,question:t.question,evidence:''};}
function migratePlan(p){for(const z of p.zones||[]){if(z.tasks===undefined)z.tasks=[z.task];if(z.capability===undefined)z.capability='';if(z.supplyNote===undefined)z.supplyNote='';if(z.materials===undefined)z.materials=[];if(z.heating===undefined){const map={'感应补热':'感应加热','等离子补热':'等离子加热','电弧补热':'电弧加热','化学补热':'化学补热'};z.heating=(z.aux||[]).filter(x=>map[x]).map(x=>({method:map[x],eta:null,power:null,hold:null,target:null,note:''}));}if(Array.isArray(z.heating))for(const h of z.heating)if(h&&h.target===undefined)h.target=null;if(z.flowFactor===undefined)z.flowFactor=null;}return p;}
