function materialLedger(p){const groups=new Map();for(const z of p.zones.filter(active)){const factor=z.lane==='main'?1:z.flowFactor;for(const m of z.materials){if(m.role!=='投入')continue;const unspecified=m.unit==='m³/t（基准未定）';const key=m.name.trim()+'|'+m.unit+(unspecified?'|'+z.id+'|'+m.id:'');if(!groups.has(key))groups.set(key,{name:m.name.trim()||'未命名物料',unit:m.unit,unspecified,known:0,missing:0,contributors:[],notes:[]});const g=groups.get(key);if(m.amount===null||factor===null)g.missing++;else g.known+=m.amount*factor;g.contributors.push(z.name);if(m.note)g.notes.push(m.note);}}return [...groups.values()];}
function makePlan(starter=false){return{id:uid(),name:starter?'多功能床 · 初始草图':'未命名构想',feed:'钢水来源、流量与成分范围待填写',product:'目标钢种与终点要求待确定',idea:'探索连续主流＋局部功能区；允许支路与循环构想',zones:starter?['receive','desulfur','clean','thermal','buffer'].map(makeZone):[]};}
